// sizes are this version's; counts and lengths are the caller's.
static inline uint8_t *ui_wire_timer_fired_write(uint8_t *p, const ui_wire_timer_fired *v) {
    ui_wire_put_u32(p + 0, v->id);
    ui_wire_put_u32(p + 4, (uint32_t)0);
    ui_wire_put_u64(p + 8, v->deadline_ns);
    ui_wire_put_u64(p + 16, v->now_ns);
    return p + UI_WIRE_TIMER_FIRED_SIZE;
}
// Appends a timer_fired event. Counts and lengths in *v must describe the data passed; padding is
// zeroed. UI_ERR_INVALID_ARGUMENT if the op would be too large, UI_ERR_OUT_OF_MEMORY.
ui_result ui_wire_timer_fired_put(ui_wire_buf *b, const ui_wire_timer_fired *v);

// ---- font_loaded -----------------------------------------------------------------------------
// event 5: u32 id (from load_font), u32 result (ui_result: 0 OK, UI_ERR_IO,
// UI_ERR_INVALID_ARGUMENT)
typedef struct ui_wire_font_loaded {
    uint32_t id;
    uint32_t result;
} ui_wire_font_loaded;
enum { UI_WIRE_FONT_LOADED_ORIGINAL = 8, UI_WIRE_FONT_LOADED_SIZE = 8 };
// Reads the fixed part from the first `sent` bytes (at least the original size):
// fields an older writer didn't send read as 0, fields a newer one appended are skipped.
static inline void ui_wire_font_loaded_read(const uint8_t *p, uint32_t sent_unused, ui_wire_font_loaded *o) {
    (void)sent_unused;
    o->id = ui_wire_get_u32(p + 0);
    o->result = ui_wire_get_u32(p + 4);
}
// Writes the fixed part (UI_WIRE_FONT_LOADED_SIZE bytes) and returns the end. Header and record
// sizes are this version's; counts and lengths are the caller's.
static inline uint8_t *ui_wire_font_loaded_write(uint8_t *p, const ui_wire_font_loaded *v) {
    ui_wire_put_u32(p + 0, v->id);
    ui_wire_put_u32(p + 4, v->result);
    return p + UI_WIRE_FONT_LOADED_SIZE;
}
// Appends a font_loaded event. Counts and lengths in *v must describe the data passed; padding is
// zeroed. UI_ERR_INVALID_ARGUMENT if the op would be too large, UI_ERR_OUT_OF_MEMORY.
ui_result ui_wire_font_loaded_put(ui_wire_buf *b, const ui_wire_font_loaded *v);

// ---- layout_measured -------------------------------------------------------------------------
// event 6: u32 request_id, u32 result (0 OK, UI_ERR_STALE_HANDLE), node handle, surface handle
// (null when stale), then four rects of f32 x, y, width, height (logical px): layout_in_parent,
// layout_in_surface, presentation_in_parent, presentation_in_surface
typedef struct ui_wire_layout_measured {
    uint32_t request_id;
    uint32_t result;
    ui_handle node;
    ui_handle surface;
    ui_wire_rect layout_in_parent;
    ui_wire_rect layout_in_surface;
    ui_wire_rect presentation_in_parent;
    ui_wire_rect presentation_in_surface;
} ui_wire_layout_measured;
enum { UI_WIRE_LAYOUT_MEASURED_ORIGINAL = 88, UI_WIRE_LAYOUT_MEASURED_SIZE = 88 };
// Reads the fixed part from the first `sent` bytes (at least the original size):
// fields an older writer didn't send read as 0, fields a newer one appended are skipped.
static inline void ui_wire_layout_measured_read(const uint8_t *p, uint32_t sent_unused, ui_wire_layout_measured *o) {
    (void)sent_unused;
    o->request_id = ui_wire_get_u32(p + 0);
    o->result = ui_wire_get_u32(p + 4);
    o->node = ui_wire_get_handle(p + 8);
    o->surface = ui_wire_get_handle(p + 16);
    ui_wire_rect_read(p + 24, UI_WIRE_RECT_SIZE, &o->layout_in_parent);
    ui_wire_rect_read(p + 40, UI_WIRE_RECT_SIZE, &o->layout_in_surface);
    ui_wire_rect_read(p + 56, UI_WIRE_RECT_SIZE, &o->presentation_in_parent);
    ui_wire_rect_read(p + 72, UI_WIRE_RECT_SIZE, &o->presentation_in_surface);
}
// Writes the fixed part (UI_WIRE_LAYOUT_MEASURED_SIZE bytes) and returns the end. Header and record
// sizes are this version's; counts and lengths are the caller's.
static inline uint8_t *ui_wire_layout_measured_write(uint8_t *p, const ui_wire_layout_measured *v) {
    ui_wire_put_u32(p + 0, v->request_id);
    ui_wire_put_u32(p + 4, v->result);
    ui_wire_put_handle(p + 8, v->node);
    ui_wire_put_handle(p + 16, v->surface);
    ui_wire_rect_write(p + 24, &v->layout_in_parent);
    ui_wire_rect_write(p + 40, &v->layout_in_surface);
    ui_wire_rect_write(p + 56, &v->presentation_in_parent);
    ui_wire_rect_write(p + 72, &v->presentation_in_surface);
    return p + UI_WIRE_LAYOUT_MEASURED_SIZE;
}
// Appends a layout_measured event. Counts and lengths in *v must describe the data passed; padding
// is zeroed. UI_ERR_INVALID_ARGUMENT if the op would be too large, UI_ERR_OUT_OF_MEMORY.
ui_result ui_wire_layout_measured_put(ui_wire_buf *b, const ui_wire_layout_measured *v);

// ---- clock -----------------------------------------------------------------------------------
// event 7: u64 now_ns: the animation clock when the core sent the buffer; first in every event
// buffer
typedef struct ui_wire_clock {
    uint64_t now_ns; // animation-clock ns
} ui_wire_clock;
enum { UI_WIRE_CLOCK_ORIGINAL = 8, UI_WIRE_CLOCK_SIZE = 8 };
// Reads the fixed part from the first `sent` bytes (at least the original size):
// fields an older writer didn't send read as 0, fields a newer one appended are skipped.
static inline void ui_wire_clock_read(const uint8_t *p, uint32_t sent_unused, ui_wire_clock *o) {
    (void)sent_unused;
    o->now_ns = ui_wire_get_u64(p + 0);
}
// Writes the fixed part (UI_WIRE_CLOCK_SIZE bytes) and returns the end. Header and record
// sizes are this version's; counts and lengths are the caller's.
static inline uint8_t *ui_wire_clock_write(uint8_t *p, const ui_wire_clock *v) {
    ui_wire_put_u64(p + 0, v->now_ns);
    return p + UI_WIRE_CLOCK_SIZE;
}
// Appends a clock event. Counts and lengths in *v must describe the data passed; padding is zeroed.
// UI_ERR_INVALID_ARGUMENT if the op would be too large, UI_ERR_OUT_OF_MEMORY.
ui_result ui_wire_clock_put(ui_wire_buf *b, const ui_wire_clock *v);

// ---- Style values ----------------------------------------------------------------------------------
// The smallest entry (in words, header included) of a value kind; 0 for a kind this
// version doesn't know (readers skip such entries by their own size).
uint32_t ui_wire_value_kind_words(uint8_t kind);
// The size of an entry holding this value, in words, header included (strings vary).
uint32_t ui_wire_style_value_words(const ui_value *v);
// Writes an entry: its header (property, kind, size) and the value. Returns the end.
uint8_t *ui_wire_style_entry_put(uint8_t *p, uint16_t property, const ui_value *v);
// Reads the value of an entry of a known kind; false if the entry is too short for it.
// A string's bytes stay in the buffer.
bool ui_wire_style_value_read(const uint8_t *entry, ui_value *out);
// True for a property (or the transition of one) this version knows.
bool ui_wire_style_prop_known(uint16_t property);
// True if a declaration of `property` with this value is valid: the property accepts the
// kind and the value is in range. Token references are accepted for every value property
// (their value is checked when resolved). `override` allows UI_VALUE_UNSET.
bool ui_wire_style_value_valid(uint16_t property, const ui_value *v, bool override);
// True if a theme token may hold this value.
bool ui_wire_style_token_value_valid(const ui_value *v);
// A string value of 1 to `max` bytes of UTF-8 without NUL.
bool ui_wire_style_string_valid(const ui_value *v, uint32_t max);

// Checks the framing of every op of a command buffer without applying anything: the
// header, then each known op's fixed part, sizes and variable data. Unknown ops are
// skipped. UI_OK or UI_ERR_MALFORMED.
ui_result ui_wire_validate_commands(const uint8_t *data, size_t size);
// The framing of one op or event: false if its payload can't hold what it describes.
bool ui_wire_command_framed(uint16_t opcode, const uint8_t *payload, uint32_t size);
bool ui_wire_event_framed(uint16_t type, const uint8_t *payload, uint32_t size);
